<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$plan = $id ? B::plan($id) : null; if ($id && $plan === null) { http_response_code(404); echo V::empty('Plano não encontrado.'); return; }
$p = $plan ?? []; $lines = static fn (?string $json): string => implode("\n", json_decode($json ?? '[]', true) ?: []); $price = static fn (mixed $v): string => $v === null ? '' : number_format((float) $v, 2, ',', ''); $manage = CmsAuth::can($admin, 'plans.manage'); ?>
<div class="cms-grid-2"><form class="cms-card" method="post" action="/acao/plan-save"><fieldset style="border:0;padding:0;margin:0"<?= $manage ? '' : ' disabled' ?>><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($id ?? 0) ?: '' ?>">
<div class="cms-form-grid"><?= V::field('Nome', 'name', $p['name'] ?? '', ['required' => true]) ?><?= V::field('Identificador', 'plan_key', $p['plan_key'] ?? '') ?></div><?= V::field('Descrição', 'description', $p['description'] ?? '', ['type' => 'textarea', 'rows' => 2]) ?>
<div class="cms-form-grid"><?= V::field('Preço mensal (R$)', 'monthly_price', $price($p['monthly_price'] ?? null), ['required' => true, 'help' => 'Ex.: 49,90']) ?><?= V::field('Preço anual (R$)', 'annual_price', $price($p['annual_price'] ?? null), ['required' => true]) ?><?= V::field('Motivo da alteração de preço', 'change_reason', '', ['help' => 'Obrigatório ao mudar o preço.']) ?></div>
<div class="cms-form-grid"><?= V::field('Benefícios (um por linha)', 'benefits', $lines($p['benefits_json'] ?? null), ['type' => 'textarea']) ?><?= V::field('Funcionalidades habilitadas (uma por linha)', 'features', $lines($p['features_json'] ?? null), ['type' => 'textarea']) ?></div>
<div class="cms-form-grid"><?= V::field('Quantidade de empresas', 'max_companies', $p['max_companies'] ?? '', ['type' => 'number', 'help' => 'Vazio: sem limite']) ?><?= V::field('Quantidade de usuários', 'max_users', $p['max_users'] ?? '', ['type' => 'number', 'help' => 'Vazio: sem limite']) ?><?= V::field('Ordem', 'sort_order', $p['sort_order'] ?? '0', ['type' => 'number']) ?><?= V::field('Situação', 'status', $p['status'] ?? 'active', ['type' => 'select', 'choices' => ['active' => 'Ativo', 'inactive' => 'Inativo']]) ?></div>
<?= V::field('Destaque', 'is_featured', $p['is_featured'] ?? '0', ['type' => 'checkbox']) ?><?= V::field('Visível no site', 'is_public', $p['is_public'] ?? '0', ['type' => 'checkbox']) ?><?php if ($manage): ?><button class="cms-btn-primary">Salvar</button><?php endif; ?></fieldset></form>
<aside class="cms-card"><h2>Histórico de preços</h2><p><small>Mudar o preço não altera assinaturas existentes: cada contrato guarda o valor contratado.</small></p><?php $history = $id ? B::priceHistory($id) : []; if ($history === []): ?><?= V::empty('Sem histórico ainda.') ?><?php endif; foreach ($history as $h): ?><p><strong><?= V::money($h['monthly_price']) ?></strong> / mês · <?= V::money($h['annual_price']) ?> / ano<br><small><?= V::date($h['valid_from']) ?> até <?= $h['valid_to'] ? V::date($h['valid_to']) : 'hoje' ?> · <?= V::e($h['author'] ?? '') ?><?= $h['change_reason'] !== '' ? ' · ' . V::e($h['change_reason']) : '' ?></small></p><?php endforeach; ?></aside></div>
